SELECT b.board_id AS boardId, b.member_id AS memberId, m.name AS writerName, b.board_type AS boardType, b.insurance_type AS insuranceType, b.title AS title, b.view_cnt AS viewCnt, b.status AS status, b.open_yn AS openYn, b.created_at AS createdAt, ( SELECT COUNT(*) FROM ins_comment c WHERE c.board_id = b.board_id AND c.deleted_yn = 'N' ) AS commentCount FROM ins_board b JOIN ins_member m ON b.member_id = m.member_id WHERE b.deleted_yn = 'N'
AND b.board_type = #{search.boardType}
AND b.insurance_type = #{search.insuranceType}
AND b.status = #{search.status}
AND b.open_yn = #{search.openYn}
AND ( b.title LIKE CONCAT('%', #{search.keyword}, '%') OR b.content LIKE CONCAT('%', #{search.keyword}, '%') )
ORDER BY b.board_id DESC LIMIT #{page.offset}, #{page.size}

